-- -----------------------------
-- Table structure for `ob_distribution`
-- -----------------------------
DROP TABLE IF EXISTS `ob_distribution`;
CREATE TABLE `ob_distribution` (
  `fx_id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` varchar(20) NOT NULL COMMENT '用户id',
  `user_a` varchar(20) DEFAULT NULL COMMENT '一级分销用户ID',
  `a_money` float DEFAULT NULL COMMENT '一级分销用户盈利金额',
  `user_b` varchar(20) DEFAULT NULL COMMENT '二级分销用户id',
  `b_money` float DEFAULT NULL COMMENT '二级分销用户盈利金额',
  `fx_time` varchar(20) NOT NULL COMMENT '时间',
  PRIMARY KEY (`fx_id`)
) ENGINE=MyISAM AUTO_INCREMENT=535 DEFAULT CHARSET=utf8;

