  PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;


-- -----------------------------
-- Table structure for `ob_kalman`
-- -----------------------------
DROP TABLE IF EXISTS `ob_kalman`;
CREATE TABLE `ob_kalman` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `generation_time` varchar(20) NOT NULL COMMENT '卡密生成时间',
  `generate_admin` varchar(30) NOT NULL COMMENT '生成的管理员',
  `state` int(11) NOT NULL DEFAULT '0' COMMENT '是否使用 0 未使用  1已经使用',
  `effective_time` int(11) DEFAULT NULL COMMENT '用户领取时间',
  `user_id` varchar(10) DEFAULT NULL COMMENT '卡密使用者',
  `number` int(10) NOT NULL COMMENT '充值金币数量',
  `kalman_pwd` text COMMENT '生成卡密',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=12227 DEFAULT CHARSET=utf8 COMMENT='卡密管理';

