  `v` float NOT NULL DEFAULT '0' COMMENT '产生的概率',
  `luck_game` text NOT NULL COMMENT '发生所需抽中的选项',
  `number` int(11) NOT NULL,
  PRIMARY KEY (`luck_id`)
) ENGINE=MyISAM AUTO_INCREMENT=11 DEFAULT CHARSET=utf8;

