  `user_id` int(11) NOT NULL COMMENT '发起提现用户id',
  `money` float NOT NULL DEFAULT '0' COMMENT '提现金额',
  `wx_id` varchar(30) NOT NULL COMMENT '微信号',
  `monery_time` text NOT NULL COMMENT '发起时间',
  `name` text NOT NULL COMMENT '用户真实姓名',
  `state` int(11) NOT NULL DEFAULT '0' COMMENT '0表示未提现，1已提现',
  `discount_time` varchar(20) DEFAULT NULL COMMENT '提现时间',
  PRIMARY KEY (`monery_id`)
) ENGINE=MyISAM AUTO_INCREMENT=36 DEFAULT CHARSET=utf8;

